// Package render writes every generated config file from a model.Stack.
//
// etc/ is owned by devstack: each render writes the full tree, rewrites only
// files whose content changed, and deletes files that no longer belong.
package render

import (
	"bytes"
	"embed"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"text/template"

	"github.com/harsha2805/devstack/internal/model"
)

//go:embed templates/*
var templateFS embed.FS

// Header starts every generated file (with the right comment marker prepended).
const Header = "Generated by devstack. Do not edit; change stack.toml or etc-custom/."

var tmpl = template.Must(template.New("").Funcs(template.FuncMap{
	"path": slashPath,
	// q joins path parts and quotes the result: {{q .Logs "nginx-error.log"}}.
	"q": func(parts ...string) string { return `"` + slashPath(filepath.Join(parts...)) + `"` },
	"join": strings.Join,
	"header": func(marker string) string {
		return marker + " " + Header
	},
	"sortedKeys": func(m map[string]string) []string {
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		return keys
	},
}).ParseFS(templateFS, "templates/*"))

func slashPath(p string) string { return filepath.ToSlash(p) }

// Files renders everything into a map of absolute path -> content.
func Files(st *model.Stack) (map[string][]byte, error) {
	out := map[string][]byte{}
	add := func(path, name string, data any) error {
		var buf bytes.Buffer
		if err := tmpl.ExecuteTemplate(&buf, name, data); err != nil {
			return fmt.Errorf("render %s: %w", name, err)
		}
		out[path] = normalizeNewlines(buf.Bytes())
		return nil
	}

	ng := filepath.Join(st.Etc, "nginx")
	if err := add(filepath.Join(ng, "nginx.conf"), "nginx.conf", st); err != nil {
		return nil, err
	}
	if err := add(filepath.Join(ng, "fastcgi.conf"), "fastcgi.conf", st); err != nil {
		return nil, err
	}
	if err := add(filepath.Join(ng, "default", "index.html"), "index.html", st); err != nil {
		return nil, err
	}
	for _, s := range st.Sites {
		data := struct {
			*model.Stack
			Site model.Site
		}{st, s}
		if err := add(filepath.Join(ng, "sites", s.Slug+".conf"), "site.conf", data); err != nil {
			return nil, err
		}
	}
	for _, p := range st.PHP {
		data := struct {
			*model.Stack
			Pool *model.PHPPool
		}{st, p}
		if err := add(p.INIPath, "php.ini", data); err != nil {
			return nil, err
		}
	}
	if st.MySQL != nil {
		if err := add(st.MySQL.INIPath, "my.ini", st); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Result says what a Write changed, relative to etc/.
type Result struct {
	Written []string
	Removed []string
}

func (r Result) Changed() bool { return len(r.Written)+len(r.Removed) > 0 }

// Write renders st into etc/ and creates the runtime folders the configs refer to.
func Write(st *model.Stack) (Result, error) {
	var res Result
	files, err := Files(st)
	if err != nil {
		return res, err
	}
	if err := Dirs(st); err != nil {
		return res, err
	}
	for path, content := range files {
		if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, content) {
			continue
		}
		if err := writeAtomic(path, content); err != nil {
			return res, err
		}
		res.Written = append(res.Written, rel(st.Etc, path))
	}

	// Prune anything in etc/ we did not just render.
	var dirs []string
	err = filepath.WalkDir(st.Etc, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			dirs = append(dirs, path)
			return nil
		}
		if _, ok := files[path]; !ok {
			if err := os.Remove(path); err != nil {
				return err
			}
			res.Removed = append(res.Removed, rel(st.Etc, path))
		}
		return nil
	})
	if err != nil {
		return res, fmt.Errorf("prune etc: %w", err)
	}
	for i := len(dirs) - 1; i > 0; i-- { // deepest first; keep etc/ itself
		os.Remove(dirs[i]) // fails harmlessly when not empty
	}
	sort.Strings(res.Written)
	sort.Strings(res.Removed)
	return res, nil
}

// Dirs creates every runtime folder the generated configs expect to exist.
func Dirs(st *model.Stack) error {
	dirs := []string{
		st.Etc, st.Logs, filepath.Join(st.Logs, "sites"),
		filepath.Join(st.EtcCustom, "nginx"),
		filepath.Join(st.Data, "devstack"),
		filepath.Join(st.Tmp, "nginx", "logs"), // nginx opens <prefix>/logs/error.log before reading its config
		filepath.Join(st.Tmp, "nginx", "temp"),
		filepath.Join(st.Tmp, "php", "sessions"),
		filepath.Join(st.Tmp, "php", "uploads"),
	}
	for _, d := range dirs {
		if err := os.MkdirAll(d, 0o755); err != nil {
			return err
		}
	}
	return nil
}

func writeAtomic(path string, content []byte) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".tmp-*")
	if err != nil {
		return err
	}
	if _, err := tmp.Write(content); err != nil {
		tmp.Close()
		os.Remove(tmp.Name())
		return err
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmp.Name())
		return err
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		os.Remove(tmp.Name())
		return err
	}
	return nil
}

// normalizeNewlines collapses runs of blank lines left by template conditionals
// and uses CRLF, which every Windows tool (and Notepad) handles.
func normalizeNewlines(b []byte) []byte {
	lines := strings.Split(strings.ReplaceAll(string(b), "\r\n", "\n"), "\n")
	var out []string
	blank := 0
	for _, l := range lines {
		l = strings.TrimRight(l, " \t")
		if l == "" {
			blank++
			if blank > 1 {
				continue
			}
		} else {
			blank = 0
		}
		out = append(out, l)
	}
	s := strings.TrimRight(strings.Join(out, "\r\n"), "\r\n") + "\r\n"
	return []byte(s)
}

func rel(base, p string) string {
	if r, err := filepath.Rel(base, p); err == nil {
		return filepath.ToSlash(r)
	}
	return p
}
